(async()=>{const $=id=>document.getElementById(id),slug=document.body.dataset.study,NS='http://www.w3.org/2000/svg',fmt=new Intl.NumberFormat('en-AU',{maximumFractionDigits:4});const node=(t,a={},text)=>{const n=document.createElementNS(NS,t);for(const[k,v]of Object.entries(a))n.setAttribute(k,v);if(text!==undefined)n.textContent=text;return n};function select(label,options,fn){const div=document.createElement('div');div.className='study-control';const l=document.createElement('label');l.textContent=label;l.htmlFor='study-choice';const s=document.createElement('select');s.id='study-choice';for(const[v,t]of options){const o=document.createElement('option');o.value=v;o.textContent=t;s.append(o)}div.append(l,s);$('study-controls').append(div);s.addEventListener('change',()=>fn(s.value));return s}function bars(labels,values,ceiling){const svg=node('svg',{viewBox:`0 0 520 ${labels.length*82+20}`,role:'img','aria-label':labels.map((l,i)=>l+': '+fmt.format(values[i])).join('; ')});const max=ceiling||Math.max(...values,1e-6);labels.forEach((l,i)=>{const y=25+i*82;svg.append(node('text',{x:5,y},l));const r=node('rect',{x:5,y:y+13,width:365*values[i]/max,height:23,rx:3,fill:i?'#345eea':'#809c88',tabindex:0});r.append(node('title',{},`${l}: ${fmt.format(values[i])}`));svg.append(r,node('text',{x:390,y:y+31},fmt.format(values[i])))});$('study-chart').replaceChildren(svg)}function table(headers,rows,issueIndices=[]){const t=document.createElement('table');t.className='study-table';const thead=document.createElement('thead'),head=document.createElement('tr');headers.forEach(x=>{const th=document.createElement('th');th.textContent=x;th.scope='col';head.append(th)});thead.append(head);t.append(thead);const body=document.createElement('tbody');rows.forEach(r=>{const tr=document.createElement('tr');r.forEach((v,i)=>{const td=document.createElement('td');td.textContent=v;if(issueIndices.includes(i))td.className=Number(v)>0?'study-issue':'study-pass';tr.append(td)});body.append(tr)});t.append(body);return t}try{const response=await fetch(`assets/studies/${slug}.json`);if(!response.ok)throw Error('Data not loaded');const d=await response.json();if(slug==='stock'){function draw(metric){const rows=d.rows,keys=metric==='f1'?['f1','baseline_f1']:['rmse','baseline_rmse'],max=metric==='f1'?1:Math.max(...rows.flatMap(r=>keys.map(k=>r[k])))*1.15;const svg=node('svg',{viewBox:'0 0 560 300',role:'group','aria-label':metric==='f1'?'Monthly positive-class F1, model versus majority-class baseline':'Monthly RMSE, model versus training-mean baseline'}),x=i=>55+i*450/(rows.length-1),y=v=>245-v/max*205;for(let i=0;i<=4;i++){const v=max*i/4;svg.append(node('line',{x1:55,x2:520,y1:y(v),y2:y(v),stroke:'#e0e5d9'}),node('text',{x:48,y:y(v)+4,'text-anchor':'end'},v.toFixed(metric==='f1'?2:3)))}keys.forEach((k,j)=>{svg.append(node('path',{d:rows.map((r,i)=>`${i?'L':'M'}${x(i)},${y(r[k])}`).join(' '),fill:'none',stroke:j?'#849787':'#345eea','stroke-width':3,'stroke-dasharray':j?'5 4':'0'}));rows.forEach((r,i)=>{const c=node('circle',{cx:x(i),cy:y(r[k]),r:5,fill:j?'#849787':'#345eea',tabindex:0,class:'study-chart-focus'});const info=`${r.month} · ${j?'Baseline':'Random Forest'} ${metric.toUpperCase()}: ${fmt.format(r[k])} · ${r.validation_rows} validation rows`;c.append(node('title',{},info));for(const ev of ['focus','mouseenter','click'])c.addEventListener(ev,()=>{$('study-detail').textContent=info});svg.append(c)})});rows.forEach((r,i)=>svg.append(node('text',{x:x(i),y:275,'text-anchor':'middle'},r.month.slice(5))));svg.append(node('text',{x:55,y:18,fill:'#345eea'},'Blue: Random Forest · dashed: baseline'));$('study-chart').replaceChildren(svg);$('study-detail').textContent=metric==='f1'?`Mean positive-class F1 ${fmt.format(d.mean_f1)}. The majority baseline predicts the negative class in every fold, giving positive-class F1 zero; this does not mean zero accuracy.`:`Mean RMSE: model ${fmt.format(d.mean_rmse)}; training-mean baseline ${fmt.format(d.mean_baseline_rmse)}. Lower is better. The model does not improve the average error in this run.`}select('View metric',[['f1','Positive-class F1'],['rmse','Regression RMSE']],draw);draw('f1')}
else if(slug==='nlp'){const map={intent_accuracy:'Intent accuracy',intent_macro_f1:'Intent macro-F1',entity_f1:'Entity F1'};function draw(k){bars([map[k]],[d[k]],1);$('study-detail').textContent=`${map[k]}: ${fmt.format(d[k])} · ${d.validation_examples} validation examples · ${d.train_examples} training examples. Accuracy and macro-F1 answer different questions; entity F1 evaluates spans.`}select('View metric',Object.entries(map),draw);draw('intent_accuracy');const box=document.createElement('div');box.className='utterance-box';const h=document.createElement('h3');h.textContent='Inspect a validation utterance';const label=document.createElement('label');label.textContent='Example ';const choice=document.createElement('select');choice.setAttribute('aria-label','Validation example');d.examples.forEach((e,i)=>{const o=document.createElement('option');o.value=i;o.textContent='Example '+(i+1);choice.append(o)});label.append(choice);const p=document.createElement('p');p.className='study-caption';const tokens=document.createElement('div');tokens.className='token-row';const detail=document.createElement('p');detail.className='study-caption';function example(i){const e=d.examples[i];p.textContent=`Intent: predicted ${e.predicted_intent} · labelled ${e.true_intent}`;tokens.replaceChildren();e.slots.forEach(t=>{const b=document.createElement('button');b.className='token'+(t.prediction!=='O'?' entity':'')+(t.prediction!==t.truth?' error':'');b.textContent=t.word;b.title=`Predicted ${t.prediction}; labelled ${t.truth}`;b.addEventListener('click',()=>{detail.textContent=`${t.word} · predicted ${t.prediction} · labelled ${t.truth}`});tokens.append(b)});detail.textContent='Select a token to inspect its slot. Blue: predicted entity; red border: label mismatch.'}choice.addEventListener('change',()=>example(Number(choice.value)));box.append(h,label,p,tokens,detail);$('study-extra').append(box);example(0)}
else if(slug==='wrangling'){function draw(k){const checks=k==='all'?d.results:d.results.filter(r=>r.missing_cells||r.order_total_mismatches||r.duplicate_order_ids||r.season_mismatches);$('study-chart').replaceChildren(table(['Output','Rows','Missing cells','Duplicate IDs','Formula mismatches','Season mismatches'],checks.map(r=>[r.dataset,r.rows,r.missing_cells,r.duplicate_order_ids,r.order_total_mismatches,r.season_mismatches]),[2,3,4,5]));$('study-detail').textContent='40 formula mismatches remain in the missing-data output. One missing cell remains in the dirty-data output. These checks identify unresolved issues; no monetary values were automatically overwritten.'}select('Show outputs',[['all','All output tables'],['issues','Only outputs with failed checks']],draw);draw('all')}
else if(slug==='survey'){function draw(k){if(k==='rmse'){bars(['Training-mean baseline','Random Forest'],[d.regression.mean_baseline_rmse,d.regression.rmse]);$('study-detail').textContent='Happiness regression RMSE on the same 100 validation rows. Lower is better; training-only preprocessing.'}else if(k==='accuracy'){bars(['Majority-class baseline','Random Forest'],[d.classification.majority_accuracy,d.classification.accuracy],1);$('study-detail').textContent='Classification accuracy on 100 validation rows. The modest improvement requires further validation.'}else{bars(['Random Forest macro-F1'],[d.classification.macro_f1],1);$('study-detail').textContent='Macro-F1 gives equal weight to each class. This result remains weak; it is not a diagnostic performance claim.'}}select('Compare task',[['rmse','Happiness regression · RMSE'],['accuracy','Classification · accuracy'],['macro','Classification · macro-F1']],draw);draw('rmse')}}catch(e){$('study-detail').textContent='Notebook results could not load. Please refresh the page.'}})();
